311	int rb_delete(rbtree_t *t, const char *key) {
312	    struct rb_node *z = find_node(t, key);
313	    if (z == NULL) return -1;
314	
315	    struct rb_node *n;
316	    bool free_own_payload = true;
317	
318	    if (z->left != NULL && z->right != NULL) {
319	        struct rb_node *y = tree_min(z->right);
320	        rb_free(z->key);
321	        if (t->value_free) t->value_free(z->value);
322	        z->key = y->key;
323	        z->value = y->value;
324	        n = y;
325	        free_own_payload = false;
326	    } else {
327	        n = z;
328	    }
329	
330	    struct rb_node *child = (n->left != NULL) ? n->left : n->right;
331	    bool n_was_black = is_black(n);
332	    transplant(t, n, child);
333	
334	    if (n_was_black) {
335	        if (child != NULL) {
336	            child->color = BLACK;             /* STEP1: absorbs the debt locally */
337	        } else {
338	            delete_fixup(t, n->parent, NULL); /* STEP2: only after transplant has run */
339	        }
340	    }
341	
342	    if (free_own_payload) {
343	        rb_free(n->key);
344	        if (t->value_free) t->value_free(n->value);
345	    }
346	    node_release(t, n);
347	    t->size--;
348	    return 0;
349	}
350	
351	size_t rb_size(const rbtree_t *t) {
352	    return t->size;
353	}
354	
355	static void foreach_inorder(const struct rb_node *n,
356	                             void (*fn)(const char *, void *, void *), void *ctx) {
357	    if (n == NULL) return;
358	    foreach_inorder(n->left, fn, ctx);
359	    fn(n->key, n->value, ctx);
360	    foreach_inorder(n->right, fn, ctx);
361	}
362	
363	void rb_foreach(const rbtree_t *t,
364	                void (*fn)(const char *key, void *value, void *ctx), void *ctx) {
365	    foreach_inorder(t->root, fn, ctx);
366	}
367	
368	struct validate_state {
369	    const char *prev_key;
370	    bool        order_ok;
371	    size_t      count;
372	};
373	
374	static void validate_walk(const struct rb_node *n, struct validate_state *st) {
375	    if (n == NULL) return;
376	    validate_walk(n->left, st);
377	    if (st->prev_key != NULL && strcmp(st->prev_key, n->key) >= 0) {
378	        st->order_ok = false;
379	    }
380	    st->prev_key = n->key;
381	    st->count++;
382	    validate_walk(n->right, st);
383	}
384	
385	static bool has_red_red(const struct rb_node *n) {
386	    if (n == NULL) return false;
387	    if (is_red(n) && (is_red(n->left) || is_red(n->right))) return true;
388	    return has_red_red(n->left) || has_red_red(n->right);
389	}
390	
391	/* Returns the subtree's black-height, or -1 if any root-to-NIL path within it
392	 * has already been found to disagree with another. NULL (NIL) contributes a
393	 * black-height of 1 by convention; a black node adds 1 on top of its children's
394	 * (equal) black-height. */
395	static int black_height(const struct rb_node *n) {
396	    if (n == NULL) return 1;
397	    int lh = black_height(n->left);
398	    if (lh == -1) return -1;
399	    int rh = black_height(n->right);
400	    if (rh == -1) return -1;
401	    if (lh != rh) return -1;
402	    return lh + (is_black(n) ? 1 : 0);
403	}
404	
405	int rb_validate(const rbtree_t *t) {
406	    if (is_red(t->root)) {
407	        fprintf(stderr, "rb_validate: invariant 1 violated (root is red)\n");
408	        return 1;
409	    }
410	    if (has_red_red(t->root)) {
411	        fprintf(stderr, "rb_validate: invariant 2 violated "
412	                         "(a red node has a red child)\n");
413	        return 2;
414	    }
415	    if (black_height(t->root) == -1) {
416	        fprintf(stderr, "rb_validate: invariant 3 violated "
417	                         "(root-to-NIL paths have differing black-height)\n");
418	        return 3;
419	    }
420	
421	    struct validate_state st = { .prev_key = NULL, .order_ok = true, .count = 0 };
422	    validate_walk(t->root, &st);
423	
424	    if (!st.order_ok) {
425	        fprintf(stderr, "rb_validate: invariant 4 violated "
426	                         "(in-order keys not strictly increasing under strcmp)\n");
427	        return 4;
428	    }
429	    if (st.count != t->size) {
430	        fprintf(stderr, "rb_validate: invariant 5 violated "
431	                         "(rb_size=%zu, actual node count=%zu)\n", t->size, st.count);
432	        return 5;
433	    }
434	    return 0;
435	}
436	
437	/* Teardown. The right-spine "Reach" walk is unchanged; the only mode-dependent
438	 * part is who reclaims node storage.
439	 *
440	 * Ordinary tree: each node is rb_free'd as the walk drops it.
441	 *
442	 * Pooled tree: nodes are NOT individually pool_free'd. Whole-tree destruction
443	 * is exactly the case pool_destroy is for -- it releases every slab whether
444	 * its slots were live, free-listed, or never carved -- so per-node pool_free
445	 * would cost an O(n) pass of poisoning and free-list churn to hand slots back
446	 * to a pool that is about to cease existing. What the walk is still required
447	 * for is the payloads: keys and values live OUTSIDE the slabs and are not
448	 * reclaimed by pool_destroy, so every key and owned value must be freed while
449	 * its node is still readable.
450	 *
451	 * Hence the ordering, which is load-bearing in both modes:
452	 *   1. capture `next` before anything is released,
453	 *   2. free the key,
454	 *   3. invoke value_free,
455	 *   4. (ordinary only) rb_free the node,
456	 * then after the walk, pool_destroy and finally the handle. Step 1 matters
457	 * more under the pool than without it: a pooled node is still live slab memory
458	 * after teardown passes over it, so a stale read would be invisible to ASan
459	 * rather than a reported use-after-free. */
460	void rb_destroy(rbtree_t *t) {
461	    if (t == NULL) return;
462	    struct rb_node *cur = t->root;
463	    while (cur != NULL) {
464	        struct rb_node *next;
465	        if (cur->left == NULL) {
466	            next = cur->right;
467	            rb_free(cur->key);
468	            if (t->value_free) t->value_free(cur->value);
469	            if (t->pool == NULL) rb_free(cur); /* pooled: reclaimed wholesale below */
470	        } else {
471	            struct rb_node *left = cur->left;
472	            cur->left = left->right;
473	            left->right = cur;
474	            next = left; /* re-enter the loop rooted at the promoted node */
475	        }
476	        cur = next;
477	    }
478	    /* Last, and only after the walk: every node it traversed physically lives
479	     * inside a slab this releases. */
480	    if (t->pool != NULL) pool_destroy(t->pool);
481	    rb_free(t);
482	}
483	
484	#ifdef RBTREE_TEST_HOOKS
485	/* Test-only hooks for exercising rb_validate's negative paths (invariants
486	 * 1-5). Compiled in only when RBTREE_TEST_HOOKS is defined (test_rbtree's
487	 * build only, per the Makefile) so production/grading builds that compile
488	 * this file without the macro never see these symbols at all. Each hook
489	 * mutates only existing struct fields on nodes the tree already owns --
490	 * no allocation, no freeing -- so rb_destroy's pointer-only teardown walk
491	 * (left/right only; it never reads color, key contents, or t->size) stays
492	 * safe to call afterward regardless of which invariant was broken.
493	 *
494	 * rb_validate checks invariants in order (1: root black, 2: no red-red,
495	 * 3: black-height, 4: ordering, 5: size) and returns on the first failure,
496	 * which is what lets each hook below isolate its target invariant's return
497	 * code even when a mutation has a side effect on a later check. */
498	
499	/* Invariant 1: flip the root red. Root-color is checked first and
500	 * unconditionally, so this isolates invariant 1 regardless of anything
501	 * else about the tree. */
502	void rb_test_force_root_red(rbtree_t *t) {
503	    if (t != NULL && t->root != NULL) t->root->color = RED;
504	}
505	
506	/* Invariant 2: find a RED node with a real (non-NULL) BLACK child and flip
507	 * that child RED, producing a red-red pair. Returns 1 if found and
508	 * corrupted, 0 if the fixture didn't have the needed shape. */
509	static struct rb_node *find_red_with_black_child(struct rb_node *n) {
510	    if (n == NULL) return NULL;
511	    if (n->color == RED &&
512	        ((n->left != NULL && n->left->color == BLACK) ||
513	         (n->right != NULL && n->right->color == BLACK))) {
514	        return n;
515	    }
516	    struct rb_node *found = find_red_with_black_child(n->left);
517	    if (found != NULL) return found;
518	    return find_red_with_black_child(n->right);
519	}
520	
521	int rb_test_force_red_red(rbtree_t *t) {
522	    if (t == NULL) return 0;
523	    struct rb_node *p = find_red_with_black_child(t->root);
524	    if (p == NULL) return 0;
525	    struct rb_node *child = (p->left != NULL && p->left->color == BLACK)
526	                             ? p->left : p->right;
527	    child->color = RED;
528	    return 1;
529	}
530	
531	/* Invariant 3: find a non-root BLACK node whose parent is BLACK and whose
532	 * own children are both BLACK-or-NIL, then flip it RED. That perturbs only
533	 * that node's subtree's black count -- it can't create a red-red pair
534	 * (parent stays black, its own children stay black) and it doesn't touch
535	 * the root, so it isolates invariant 3 rather than tripping 1 or 2 first.
536	 * Returns 1 if found and corrupted, 0 otherwise. */
537	static struct rb_node *find_isolated_black_flip_target(struct rb_node *n) {
538	    if (n == NULL) return NULL;
539	    if (n->parent != NULL && n->color == BLACK && is_black(n->parent) &&
540	        is_black(n->left) && is_black(n->right)) {
541	        return n;
542	    }
543	    struct rb_node *found = find_isolated_black_flip_target(n->left);
544	    if (found != NULL) return found;
545	    return find_isolated_black_flip_target(n->right);
546	}
547	
548	int rb_test_break_black_height(rbtree_t *t) {
549	    if (t == NULL) return 0;
550	    struct rb_node *n = find_isolated_black_flip_target(t->root);
551	    if (n == NULL) return 0;
552	    n->color = RED;
553	    return 1;
554	}
555	
556	/* Invariant 4: swap the key pointers of two existing nodes (located by
557	 * their current key values), which breaks in-order strictly-increasing
558	 * order without touching allocation, color, or structure -- each string is
559	 * still owned by exactly one node afterward, just a different one. Returns
560	 * 1 if both keys were found and swapped, 0 otherwise. */
561	static struct rb_node *find_by_key(struct rb_node *n, const char *key) {
562	    while (n != NULL) {
