405	int rb_validate(const rbtree_t *t) {
406	    if (is_red(t->root)) {
407	        fprintf(stderr, "rb_validate: invariant 1 violated (root is red)\n");
408	        return 1;
409	    }
410	    if (has_red_red(t->root)) {
411	        fprintf(stderr, "rb_validate: invariant 2 violated "
412	                         "(a red node has a red child)\n");
413	        return 2;
414	    }
415	    if (black_height(t->root) == -1) {
416	        fprintf(stderr, "rb_validate: invariant 3 violated "
417	                         "(root-to-NIL paths have differing black-height)\n");
418	        return 3;
419	    }
420	
421	    struct validate_state st = { .prev_key = NULL, .order_ok = true, .count = 0 };
422	    validate_walk(t->root, &st);
423	
424	    if (!st.order_ok) {
425	        fprintf(stderr, "rb_validate: invariant 4 violated "
426	                         "(in-order keys not strictly increasing under strcmp)\n");
427	        return 4;
428	    }
429	    if (st.count != t->size) {
430	        fprintf(stderr, "rb_validate: invariant 5 violated "
431	                         "(rb_size=%zu, actual node count=%zu)\n", t->size, st.count);
432	        return 5;
433	    }
434	    return 0;
435	}
