484	#ifdef RBTREE_TEST_HOOKS
485	/* Test-only hooks for exercising rb_validate's negative paths (invariants
486	 * 1-5). Compiled in only when RBTREE_TEST_HOOKS is defined (test_rbtree's
487	 * build only, per the Makefile) so production/grading builds that compile
488	 * this file without the macro never see these symbols at all. Each hook
489	 * mutates only existing struct fields on nodes the tree already owns --
490	 * no allocation, no freeing -- so rb_destroy's pointer-only teardown walk
491	 * (left/right only; it never reads color, key contents, or t->size) stays
492	 * safe to call afterward regardless of which invariant was broken.
493	 *
494	 * rb_validate checks invariants in order (1: root black, 2: no red-red,
495	 * 3: black-height, 4: ordering, 5: size) and returns on the first failure,
496	 * which is what lets each hook below isolate its target invariant's return
497	 * code even when a mutation has a side effect on a later check. */
