static unsigned char *hits;           /* per-value value_free call counts */
static void mark_free(void *v) { (*(unsigned char *)v)++; }
struct job { rbtree_t *t; int foreach; int recursive; long seen; int order_ok; const char *prev; };
static void visit(const char *k, void *v, void *ctx) {
    (void)v; struct job *j = ctx;
    if (j->prev && strcmp(j->prev, k) >= 0) j->order_ok = 0;
    j->prev = k; j->seen++;
}
static void *worker(void *arg) {
    struct job *j = arg;
    if (j->foreach) rb_foreach(j->t, visit, j);
    if (j->recursive) x_destroy_recursive(j->t); else rb_destroy(j->t);
    return NULL;
