    hits = calloc((size_t)n, 1);
    rbtree_t *t = build(pooled, n);
    if (rb_size(t) != (size_t)n || rb_validate(t) != 0) { fprintf(stderr, "bad build\n"); return 2; }
    if (!strcmp(shape, "left")) x_make_left_spine(t);
