    printf("%s %s n=%ld foreach_seen=%ld order_ok=%d allocs_in_thread=%ld values_freed_exactly_once=%ld/%ld\n",
           pooled ? "pooled" : "heap", shape, n, j.seen, j.order_ok, allocs, once, n);
