        printf(failures == 0 ? "\\nAll stress tests passed (N=%lu).\\n"
                             : "\\n%d stress test(s) FAILED.\\n",
               failures == 0 ? n : (unsigned long)failures);
        return failures == 0 ? 0 : 1;
    }

    /* Pass 1: ordinary rb_malloc node storage (the HW1 + M1 baseline). */'''
